suppressPackageStartupMessages({library(data.table);library(ggplot2)})
out='output/external_rbp_splice_comparison/'
p=fread(paste0(out,'splice_bin_profiles.tsv'));p[,RBP:=factor(RBP,levels=c('MSI2','QKI','PUM2','ELAVL1'))];p[,boundary:=factor(boundary,levels=c('donor','acceptor'))]
fig=function(d)ggplot(d,aes(bin_center,observed_expected))+geom_ribbon(aes(ymin=null_low_OE,ymax=null_high_OE),fill='grey80')+geom_hline(yintercept=1,lty=2)+geom_vline(xintercept=0,color='grey40')+geom_line(color='#226778')+facet_grid(RBP~boundary)+theme_bw()+labs(x='Transcript-oriented distance to boundary (nt)',y='Observed / matched-background peak fraction',title='Called sites near splice boundaries',subtitle='10-nt bins; same GENCODEv26 landmarks; 500 within-context permutations')
for(w in c(250,1000)){stem=if(w==250)'external_rbp_splice_comparison' else 'external_rbp_splice_comparison_1000';for(e in c('png','pdf'))ggsave(paste0(out,stem,'.',e),fig(p[abs(bin_center)<w]),width=10,height=11,dpi=220)}
z=fread(paste0(out,'splice_zone_enrichment.tsv'));z[,empirical_p_depletion:=vapply(seq_len(.N),function(i){m=readRDS(paste0(out,RBP[i],'_',boundary[i],'_null_bin_counts.rds')); bins=seq(-1000,990,10); v=colSums(m[bins>=zone_start[i]&bins<zone_end[i],,drop=FALSE]);(1+sum(v<=observed_peaks[i]))/501},numeric(1))];z[,empirical_p_two_sided:=pmin(1,2*pmin(empirical_p,empirical_p_depletion))];z[,q_BH_enrichment:=p.adjust(empirical_p,'BH')];fwrite(z,paste0(out,'splice_zone_enrichment.tsv'),sep='\t');wide=dcast(z[zone%in%c('exon_proximal','intron_proximal')],RBP~boundary+zone,value.var='enrichment');wide[,`:=`(donor_exon_intron_contrast=donor_exon_proximal/donor_intron_proximal,acceptor_exon_intron_contrast=acceptor_exon_proximal/acceptor_intron_proximal)];fwrite(wide,paste0(out,'splice_zone_summary.tsv'),sep='\t')
# Shape correlations are descriptive and not independent significance tests.
pp=dcast(p[abs(bin_center)<250],boundary+bin_center~RBP,value.var='observed_expected');cor=rbindlist(lapply(c('QKI','PUM2','ELAVL1'),function(r)pp[,.(comparator=r,pearson=cor(MSI2,get(r),use='complete.obs'),spearman=cor(MSI2,get(r),method='spearman',use='complete.obs')),by=boundary]));fwrite(cor,paste0(out,'profile_shape_correlations.tsv'),sep='\t')
s=fread(paste0(out,'DATA_SOURCES.tsv'));s=s[RBP!='MSI2'];s[,DOI:=ifelse(RBP=='ELAVL1','10.1038/nmeth.1608','10.1016/j.cell.2010.03.009')];s=rbind(s,data.table(RBP='MSI2',publication='Unconfirmed endogenous provenance',PMID='Unconfirmed',method='Supplied omniCLIP reference peaks',cell_line='Unconfirmed for supplied reference BED',original_build='hg38/GRCh38',source='User-supplied data/MSI2_peaks_omniCLIP.bed',filename='MSI2_peaks_omniCLIP.bed',original_N=58555,coordinate_definition='Source BED summit columns7-8; score>=1 and same-strand merge yield43794 representatives',url='Local supplied file',selection_reason='Existing reference peak universe; endogenous identity provisionally endorsed by user',DOI='Unconfirmed'),fill=TRUE);fwrite(s,paste0(out,'DATA_SOURCES.tsv'),sep='\t')
